# Import ASCII Data
h243 <- read_fwf(
    "data/consolidated_data/2022/h243.dat",
    col_positions = fwf_positions(
        start = pos_start,
        end = pos_end,
        col_names = var_names
    ),
    col_types = var_types
)

h243 <- h243 |>
    rename(
        panel_encrypted_du_identifier = DUID,
        person_number_portion_of_persid = PID,
        person_id_duid_pid = DUPERSID,
        panel_number = PANEL,
        survey_data_year = DATAYEAR,
        family_id_student_merged_in_r3_1 = FAMID31,
        family_id_student_merged_in_r4_2 = FAMID42,
        family_id_student_merged_in_r5_3 = FAMID53,
        family_id_student_merged_in_12_31_22 = FAMID22,
